mapper.select:
SELECT cb.CONT_NO ,cb.CONT_SEQ ,cb.ORG_NO ,cb.BRCH_NO ,om.ORG_CD ,bm.BRCH_CD ,cb.SAVE_CAN_YN ,cb.USE_CAN_YN ,cb.CONT_BRCH_STS_CD ,cb.TOTAL_ISU_ABLE_CNT ,cb.TOTAL_ISU_ABLE_PT ,cb.REG_USER_ID ,cb.REG_DT ,cb.LAST_MOD_USER_ID ,cb.LAST_MOD_DT FROM CONT_BRCH cb INNER JOIN ORG_MST om ON om.ORG_NO = cb.ORG_NO INNER JOIN BRCH_MST bm ON bm.BRCH_NO = cb.BRCH_NO WHERE 1 = 1
AND cb.CONT_NO = #{contNo}
AND cb.CONT_SEQ = #{contSeq}
AND cb.ORG_NO = #{orgNo}
AND cb.BRCH_NO = #{brchNo}
AND om.ORG_CD = #{orgCd}
AND bm.BRCH_CD = #{brchCd}

SELECT
COUNT(*)
FROM CONT_BRCH cb
    INNER JOIN ORG_MST om ON om.ORG_NO = cb.ORG_NO
    INNER JOIN BRCH_MST bm ON bm.BRCH_NO = cb.BRCH_NO
WHERE 1 = 1

    AND cb.CONT_NO = #{contNo}


    AND cb.CONT_SEQ = #{contSeq}


    AND cb.BRCH_NO = #{brchNo}


    AND om.ORG_CD = #{orgCd}


    AND bm.BRCH_CD = #{brchCd}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY cb.CONT_NO, cb.ORG_NO, cb.BRCH_NO) ROW_NUM ,cb.CONT_NO ,cb.CONT_SEQ ,cb.ORG_NO ,cb.BRCH_NO ,om.ORG_CD ,bm.BRCH_CD ,cb.SAVE_CAN_YN ,cb.USE_CAN_YN ,cb.CONT_BRCH_STS_CD ,cb.TOTAL_ISU_ABLE_CNT ,cb.TOTAL_ISU_ABLE_PT ,cb.REG_USER_ID ,cb.REG_DT ,cb.LAST_MOD_USER_ID ,cb.LAST_MOD_DT FROM CONT_BRCH cb INNER JOIN ORG_MST om ON om.ORG_NO = cb.ORG_NO INNER JOIN BRCH_MST bm ON bm.BRCH_NO = cb.BRCH_NO WHERE 1 = 1
AND cb.CONT_NO = #{contNo}
AND cb.CONT_SEQ = #{contSeq}
AND cb.BRCH_NO = #{brchNo}
AND om.ORG_CD = #{orgCd}
AND bm.BRCH_CD = #{brchCd}
ORDER BY cb.CONT_NO, cb.ORG_NO, cb.BRCH_NO ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
